#!/usr/bin/env python3
"""Standalone, deterministic resource-evidence reporter for autorecomp (#26).

Reads a pipeline ``report.json`` plus an OPTIONAL independent measured
RSS/disk JSON (both paths supplied on the command line) and emits a
deterministic Markdown and JSON summary of four resource metrics:

* generated bytes -- ``report.resources.generated_source_bytes``
* build seconds   -- ``report.resources.build_seconds``
* peak RSS        -- ``report.resources.peak_rss_bytes``
* disk free       -- ``report.disk_guard.free_bytes``

This tool does not measure or fabricate anything. It only transcribes values
already present in the supplied JSON files, so there are no built-in paths and
no guessed numbers. A null or absent measurement is reported explicitly as
``NOT TESTED`` -- never as zero, "n/a" or an estimate. A present value with an
invalid type/negative magnitude is flagged ``INVALID``; a value that disagrees
with the optional independent measurement is flagged ``MISMATCH``. Both are
"tampered values detected" signals, and the offending number is never shown as
a clean measurement.

Optional measured JSON schema (every field is optional)::

    {
      "schema": 1,
      "generated_bytes": 4096,
      "build_seconds": 9.75,
      "peak_rss_bytes": 123456,
      "disk_free_bytes": 987654
    }

Values nested under a ``resources`` or ``measurements`` object are also
accepted. A field left null/absent in this file simply does not provide an
independent reading for that metric.

Usage::

    python3 -m tools.autorecomp.resource_report \
        --report <report.json> [--measured <measured.json>] \
        [--out-md <summary.md>] [--out-json <summary.json>] [--strict]
"""
from __future__ import annotations

import argparse
import json
import math
import sys
from pathlib import Path
from typing import Any, NamedTuple

SCHEMA_VERSION = 1
GENERATOR = "tools/autorecomp/resource_report.py"

NOT_TESTED = "NOT TESTED"
MEASURED = "MEASURED"
INVALID = "INVALID"
MISMATCH = "MISMATCH"

_TAMPERED_STATUSES = (INVALID, MISMATCH)

# Build seconds are rounded to 2 decimals in report.json; allow a centisecond
# of slack when cross-checking an independent reading. Byte counts are exact.
SECONDS_TOLERANCE = 0.01


class MetricSpec(NamedTuple):
    key: str
    label: str
    unit: str
    report_path: tuple[str, ...]
    measured_key: str
    integer: bool


# Fixed order -> deterministic Markdown/JSON. This is the contract of the
# summary: four metrics, always in this order, never invented.
METRICS: tuple[MetricSpec, ...] = (
    MetricSpec("generated_bytes", "Generated bytes", "bytes",
               ("resources", "generated_source_bytes"), "generated_bytes", True),
    MetricSpec("build_seconds", "Build seconds", "s",
               ("resources", "build_seconds"), "build_seconds", False),
    MetricSpec("peak_rss_bytes", "Peak RSS", "bytes",
               ("resources", "peak_rss_bytes"), "peak_rss_bytes", True),
    MetricSpec("disk_free_bytes", "Disk free", "bytes",
               ("disk_guard", "free_bytes"), "disk_free_bytes", True),
)


class _Missing:
    """Sentinel for a key that is genuinely absent from a JSON object."""


MISSING = _Missing()


def load_json(path: Path) -> dict:
    """Load a JSON object from a caller-supplied path; fail closed on bad input."""
    data = json.loads(Path(path).read_text(encoding="utf-8"))
    if not isinstance(data, dict):
        raise ValueError(f"{path}: expected a JSON object")
    return data


def _get(data: Any, keys: tuple[str, ...]) -> Any:
    """Walk a nested object, returning MISSING if any key is absent."""
    cur = data
    for key in keys:
        if not isinstance(cur, dict) or key not in cur:
            return MISSING
        cur = cur[key]
    return cur


def _measured_value(measured: dict | None, key: str) -> Any:
    """Read one optional measurement from any supported container."""
    if not isinstance(measured, dict):
        return MISSING
    if key in measured:
        return measured[key]
    for container in ("resources", "measurements"):
        block = measured.get(container)
        if isinstance(block, dict) and key in block:
            return block[key]
    return MISSING


def _is_number(value: Any, integer: bool) -> bool:
    """True only for a real, finite, non-negative int (or float for seconds)."""
    if isinstance(value, bool):  # bool is an int subclass: never a measurement
        return False
    if integer:
        return isinstance(value, int) and value >= 0
    if isinstance(value, int) and not isinstance(value, bool):
        return value >= 0
    if isinstance(value, float):
        return math.isfinite(value) and value >= 0
    return False


def _coerce(value: Any, integer: bool) -> tuple[Any | None, str]:
    """Return (clean number or None, status) for one raw reading."""
    if value is MISSING or value is None:
        return None, NOT_TESTED
    if not _is_number(value, integer):
        return None, INVALID
    return value, MEASURED


def _agrees(a: Any, b: Any, spec: MetricSpec) -> bool:
    if spec.integer:
        return int(a) == int(b)
    return abs(float(a) - float(b)) <= SECONDS_TOLERANCE


def _fmt(value: Any, unit: str) -> str:
    if unit == "bytes":
        return f"{int(value)} B"
    return f"{value} {unit}"


def _source_for(report_status: str, measured_status: str) -> str | None:
    if report_status == MEASURED and measured_status == MEASURED:
        return "report+measured"
    if report_status == MEASURED:
        return "report"
    if measured_status == MEASURED:
        return "measured"
    return None


def analyse(report: dict, measured: dict | None = None) -> dict:
    """Build a deterministic, JSON-serialisable resource-evidence summary.

    ``report`` is the pipeline ``report.json`` object; ``measured`` is the
    optional independent measurement object. Neither is mutated.
    """
    metrics: list[dict] = []
    findings: list[str] = []

    for spec in METRICS:
        report_raw = _get(report, spec.report_path)
        measured_raw = _measured_value(measured, spec.measured_key)
        report_value, report_status = _coerce(report_raw, spec.integer)
        measured_value, measured_status = _coerce(measured_raw, spec.integer)

        if INVALID in (report_status, measured_status):
            status = INVALID
            value = None
            if report_status == INVALID:
                findings.append(
                    f"{spec.label}: report value {report_raw!r} is not a valid "
                    f"non-negative {'integer' if spec.integer else 'number'}")
            if measured_status == INVALID:
                findings.append(
                    f"{spec.label}: independent measurement {measured_raw!r} is "
                    f"not a valid non-negative {'integer' if spec.integer else 'number'}")
        elif report_status == MEASURED and measured_status == MEASURED:
            if _agrees(report_value, measured_value, spec):
                status, value = MEASURED, report_value
            else:
                status, value = MISMATCH, None
                findings.append(
                    f"{spec.label}: report={report_value!r} disagrees with "
                    f"independent measurement={measured_value!r}")
        elif report_status == MEASURED:
            status, value = MEASURED, report_value
        elif measured_status == MEASURED:
            status, value = MEASURED, measured_value
        else:
            status, value = NOT_TESTED, None

        metrics.append({
            "key": spec.key,
            "label": spec.label,
            "unit": spec.unit,
            "value": value,
            "status": status,
            "source": _source_for(report_status, measured_status) if status == MEASURED else None,
            "report_value": report_value,
            "measured_value": measured_value,
        })

    tested = sum(1 for m in metrics if m["status"] == MEASURED)
    tampered = any(m["status"] in _TAMPERED_STATUSES for m in metrics)
    return {
        "schema": SCHEMA_VERSION,
        "generator": GENERATOR,
        "verdict": "TAMPERED" if tampered else "OK",
        "metrics_tested": tested,
        "metrics": metrics,
        "findings": findings,
    }


def build_summary(report: dict, measured: dict | None = None, *,
                  report_label: str | None = None,
                  measured_label: str | None = None) -> dict:
    """``analyse`` plus the caller-supplied provenance labels (no timestamps)."""
    summary = analyse(report, measured)
    summary["report"] = report_label
    summary["measured"] = measured_label
    return summary


def dumps_json(summary: dict) -> str:
    """Canonical JSON: sorted keys, fixed indentation, trailing newline."""
    return json.dumps(summary, indent=2, sort_keys=True, ensure_ascii=True) + "\n"


def render_markdown(summary: dict) -> str:
    """Render a deterministic Markdown table from a summary."""
    lines = [
        "# Autorecomp resource evidence",
        "",
        f"Report: `{summary.get('report') or 'not supplied'}`",
        "Independent measurement: "
        f"`{summary.get('measured') or 'not supplied'}`",
        "",
        "| Metric | Value | Status | Source |",
        "|---|---|---|---|",
    ]
    for metric in summary["metrics"]:
        shown = _fmt(metric["value"], metric["unit"]) if metric["status"] == MEASURED \
            else metric["status"]
        lines.append(
            f"| {metric['label']} | {shown} | {metric['status']} | "
            f"{metric['source'] or '—'} |")
    lines += [
        "",
        f"Verdict: **{summary['verdict']}** "
        f"({summary['metrics_tested']}/{len(summary['metrics'])} metrics tested)",
        "",
        "## Findings",
        "",
    ]
    lines += [f"- {finding}" for finding in summary["findings"]] or ["- none"]
    lines.append("")
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--report", required=True, type=Path,
                    help="pipeline reports/report.json (caller-supplied path)")
    ap.add_argument("--measured", type=Path,
                    help="optional independent RSS/disk measurement JSON")
    ap.add_argument("--out-md", type=Path, help="write Markdown here")
    ap.add_argument("--out-json", type=Path, help="write the JSON summary here")
    ap.add_argument("--strict", action="store_true",
                    help="exit 1 when any value is flagged as tampered")
    args = ap.parse_args(argv)

    try:
        report = load_json(args.report)
        measured = load_json(args.measured) if args.measured else None
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        print(f"resource_report: {exc}", file=sys.stderr)
        return 2

    summary = build_summary(
        report, measured,
        report_label=str(args.report),
        measured_label=str(args.measured) if args.measured else None)
    markdown = render_markdown(summary)

    if args.out_md:
        args.out_md.parent.mkdir(parents=True, exist_ok=True)
        args.out_md.write_text(markdown, encoding="utf-8")
    if args.out_json:
        args.out_json.parent.mkdir(parents=True, exist_ok=True)
        args.out_json.write_text(dumps_json(summary), encoding="utf-8")
    if not args.out_md and not args.out_json:
        print(markdown)

    if args.strict and summary["verdict"] == "TAMPERED":
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
